// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays. update_time is set to the same instant: the
// delete is the record's latest write, which a reader by update time can tell
// from any write after it.
func (r *GormPromotionRepository) Delete(ctx context.Context, name string) error {
	key, err := r.rowKey(name)
	if err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	res := r.markDeleted(ctx, r.DB, key)
	if res.Error != nil {
		return repox.MapGormErr(res.Error)
	}
	if res.RowsAffected == 0 {
		return repox.ErrNotFound
	}
	return nil
}

// markDeleted sets the soft-delete mark on the live row found by key
// (rowKey) through db: Delete's write, which a Batch runs inside its
// transaction.
func (r *GormPromotionRepository) markDeleted(ctx context.Context, db *gorm.DB, key string) *gorm.DB {
	now := time.Now()
	return db.WithContext(ctx).Model(&promotion.Promotion{}).
		Where("name = ? AND delete_time IS NULL", key).
		Updates(map[string]any{"delete_time": now, "update_time": now, "etag": repox.NewULID(), "expire_time": repox.ExpireAt(now, r.Retention)})
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GormPromotionRepository) Undelete(ctx context.Context, name string) (*promotionv1.Promotion, error) {
	key, err := r.rowKey(name)
	if err != nil {
		return nil, err
	}
	res := r.DB.WithContext(ctx).Model(&promotion.Promotion{}).
		Where("name = ? AND delete_time IS NOT NULL", key).
		Updates(map[string]any{"delete_time": nil, "etag": repox.NewULID(), "expire_time": nil})
	if res.Error != nil {
		return nil, repox.MapGormErr(res.Error)
	}
	if res.RowsAffected == 0 {
		if _, err := r.get(ctx, key); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, key)
}

// Purge removes the record addressed by its resource name for good.
func (r *GormPromotionRepository) Purge(ctx context.Context, name string) error {
	key, err := r.rowKey(name)
	if err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	_, err = r.purge(ctx, r.DB, key, name, true)
	return repox.MapGormErr(err)
}

// purgeTx removes the row found by key (rowKey) inside tx, with the
// value-object rows it owns; gorm.ErrRecordNotFound when there is no such row.
func (r *GormPromotionRepository) purgeTx(ctx context.Context, tx *gorm.DB, key string) error {
	var existing promotion.Promotion
	if err := tx.WithContext(ctx).Preload("Start").Preload("Start.Day").Preload("Start.Clock").Preload("End").Preload("End.Day").Preload("End.Clock").Preload("Description").Preload("Description.PurgeDay").Preload("Description.FormattedTextTexts", func(db *gorm.DB) *gorm.DB { return db.Order("id") }).Preload("Description.ListItems", func(db *gorm.DB) *gorm.DB { return db.Order("id") }).First(&existing, "name = ?", key).Error; err != nil {
		return err
	}
	if err := promotion.NewPromotionStore(tx).DeleteByID(ctx, existing.ID); err != nil {
		return err
	}
	if d7 := existing.Start; d7 != nil {
		if err := tx.WithContext(ctx).Delete(&promotion.DateOrTimeOrDateTime{}, "id = ?", d7.ID).Error; err != nil {
			return err
		}
		if d8 := d7.Day; d8 != nil {
			if err := tx.WithContext(ctx).Delete(&promotion.Date{}, "id = ?", d8.ID).Error; err != nil {
				return err
			}
		}
		if d9 := d7.Clock; d9 != nil {
			if err := tx.WithContext(ctx).Delete(&promotion.TimeOfDay{}, "id = ?", d9.ID).Error; err != nil {
				return err
			}
		}
	}
	if d16 := existing.End; d16 != nil {
		if err := tx.WithContext(ctx).Delete(&promotion.DateOrTimeOrDateTime{}, "id = ?", d16.ID).Error; err != nil {
			return err
		}
		if d17 := d16.Day; d17 != nil {
			if err := tx.WithContext(ctx).Delete(&promotion.Date{}, "id = ?", d17.ID).Error; err != nil {
				return err
			}
		}
		if d18 := d16.Clock; d18 != nil {
			if err := tx.WithContext(ctx).Delete(&promotion.TimeOfDay{}, "id = ?", d18.ID).Error; err != nil {
				return err
			}
		}
	}
	if d27 := existing.Description; d27 != nil {
		for i28 := range d27.FormattedTextTexts {
			d29 := &d27.FormattedTextTexts[i28]
			if err := tx.WithContext(ctx).Delete(&promotion.FormattedTextText{}, "id = ?", d29.ID).Error; err != nil {
				return err
			}
		}
		for i30 := range d27.ListItems {
			d31 := &d27.ListItems[i30]
			if err := tx.WithContext(ctx).Delete(&promotion.ListItem{}, "id = ?", d31.ID).Error; err != nil {
				return err
			}
		}
		if err := tx.WithContext(ctx).Delete(&promotion.Description{}, "id = ?", d27.ID).Error; err != nil {
			return err
		}
		if d32 := d27.PurgeDay; d32 != nil {
			if err := tx.WithContext(ctx).Delete(&promotion.Date{}, "id = ?", d32.ID).Error; err != nil {
				return err
			}
		}
	}
	return nil
}

// purge removes the row found by key (rowKey), named name, for good through
// db -- unless something
// still refers to it, when it keeps the row and reports kept: a row of this
// database holding a foreign key to it (asked first, then caught again from
// the constraint itself), or, when askReferrers, a referrer in another
// database or service (r.Refs). A purge never fails, and never cascades,
// because of a referrer. gorm.ErrRecordNotFound when there is no such row.
func (r *GormPromotionRepository) purge(ctx context.Context, db *gorm.DB, key, name string, askReferrers bool) (kept bool, err error) {
	if askReferrers && r.Refs.KeepOnPurge(ctx, "hotel.opentravel.org/Promotion", name) {
		return true, nil
	}
	// A savepoint inside a caller's transaction: a foreign key the query
	// above does not know (one from another generator run) rolls back only
	// this purge.
	err = db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		return r.purgeTx(ctx, tx, key)
	})
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GormPromotionRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, r.DB, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			key, err := r.rowKey(m.GetName())
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, r.DB, key, m.GetName(), true)
			switch {
			case errors.Is(err, gorm.ErrRecordNotFound):
			case err != nil:
				return res, repox.MapGormErr(err)
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

// ListByKeys reads every record whose filter field field is one of keys; see
// repox.ListByKeys.
func (r *GormPromotionRepository) ListByKeys(ctx context.Context, field string, keys []string, in repox.ListInput) ([]*promotionv1.Promotion, error) {
	return repox.ListByKeys(ctx, field, keys, in, func(ctx context.Context, in repox.ListInput) ([]*promotionv1.Promotion, string, error) {
		return r.List(ctx, "hotels/-", in)
	})
}

// Compile-time proof the adapter satisfies the interface.
var _ PromotionRepository = (*GormPromotionRepository)(nil)

// gormBatch is Batch on GORM: queued writes run in the Unit's transaction on
// Commit.
type gormBatch struct {
	u         *repox.Unit
	db        *gorm.DB
	retention time.Duration
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *gormBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// CreatePromotion queues a create and returns the name the record will have.
func (b *gormBatch) CreatePromotion(parent string, in *promotionv1.Promotion) (string, error) {
	r := &GormPromotionRepository{DB: b.db}
	m, named, err := r.newRow(parent, in)
	if err != nil {
		return "", err
	}
	var locks []string
	if k, ok := any(m).(interface{ NoOverlapKeys() []string }); ok {
		locks = k.NoOverlapKeys()
	}
	queuePromotionReferences(b.u, named, nil)
	b.u.QueueGorm(locks, func(ctx context.Context, tx *gorm.DB) error {
		return r.insertTx(ctx, tx, named, m)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/Promotion", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdatePromotion queues Update; in.Etag, when set, guards it, and a guard
// that fails rolls the whole batch back.
func (b *gormBatch) UpdatePromotion(in *promotionv1.Promotion, paths []string) {
	r := &GormPromotionRepository{DB: b.db}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		b.u.Fail(err)
		return
	}
	queuePromotionReferences(b.u, in, paths)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateTx(ctx, tx, key, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/Promotion", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getPromotion)})
}

// UpdatePromotionWithOutputOnly queues UpdateWithOutputOnly; in.Etag, when
// set, guards it, and a guard that fails rolls the whole batch back.
func (b *gormBatch) UpdatePromotionWithOutputOnly(in *promotionv1.Promotion, paths, outputPaths []string) {
	r := &GormPromotionRepository{DB: b.db}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		b.u.Fail(err)
		return
	}
	queuePromotionReferences(b.u, in, paths)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateTx(ctx, tx, key, in, paths, outputPaths)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/Promotion", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getPromotion)})
}

// UpdatePromotionOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards it.
func (b *gormBatch) UpdatePromotionOutputOnly(in *promotionv1.Promotion, paths []string) {
	r := &GormPromotionRepository{DB: b.db}
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateOutputOnlyTx(ctx, tx, in, paths)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/Promotion", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getPromotion)})
}

// DeletePromotion queues a soft delete. A record already deleted or gone is
// not an error: two batches deleting the same record must not fail each other.
func (b *gormBatch) DeletePromotion(name string) {
	r := &GormPromotionRepository{DB: b.db, Retention: b.retention}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	queuePromotionDelete(b.u, name, false)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.markDeleted(ctx, tx, key).Error
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/Promotion", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getPromotion)})
}

// PurgePromotion queues the record's removal for good. A record already
// gone is not an error: two batches clearing the same row must not fail each
// other.
func (b *gormBatch) PurgePromotion(name string) {
	// A record something still refers to is kept, as Purge keeps it.
	r := &GormPromotionRepository{DB: b.db, Refs: b.u.Conn().References}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	keep := queuePromotionPurge(b.u, name)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		if *keep {
			return nil
		}
		if _, err := r.purge(ctx, tx, key, name, false); err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
			return err
		}
		return nil
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/Promotion", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getPromotion)})
}
